import sys; sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/deps')
import zstandard as zstd, io
from classify_responses import complete_frames
def raw_frame(payload):
    out=bytearray((0xfd2fb528).to_bytes(4,'little')); out+=bytes([0x20, len(payload)&0xff])
    out+=((0)|(0<<1)|(len(payload)<<3)|(1<<0)).to_bytes(3,'little'); out+=payload
    return bytes(out)
def rle_frame(n):
    out=bytearray((0xfd2fb528).to_bytes(4,'little')); out+=bytes([0x20, n])
    out+=((1)|(1<<1)|(n<<3)|(1<<0)).to_bytes(3,'little'); out+=bytes([0x41])
    return bytes(out)
b=rle_frame(200); complete_frames(b); print('rle ok', zstd.ZstdDecompressor().stream_reader(io.BytesIO(b),read_across_frames=True).read()[:3])
b=b''.join([raw_frame(b'aa'),raw_frame(b'bb'), (0x184D2A50).to_bytes(4,'little')+(4).to_bytes(4,'little')+b'xxxx', raw_frame(b'cc')])
complete_frames(b); print('concat ok', zstd.ZstdDecompressor(max_window_size=128*1024**2).stream_reader(io.BytesIO(b),read_across_frames=True).read())
for bad,label in [(raw_frame(b'abc')[:-1],'trunc'),(raw_frame(b'abc')+b'\x00','extra'),(bytes([0x28,0xb5,0x2f,0xfd,0x08,0x00]),'reservedbit'),(bytes([0x28,0xb5,0x2f,0xfd,0x10,0x00]),'unusedbit'),(bytes([0x28,0xb5,0x2f,0xfd,0x1f,0x07,0xff,0xff]),'bigwindow'),(b'nope','magic')]:
    try:
        complete_frames(bad); print('MISSED',label)
    except Exception as e: print('rejected',label,type(e).__name__,e)
print('unused bit accepted:', complete_frames(bytes([0x28,0xb5,0x2f,0xfd,0x10,0x00, 0x01,0x00,0x00])+b'A'))
"
